def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    ys, xs = np.nonzero(g == 1)
    # Determine mirror type
    if len(set(xs)) == 1:
        c = xs[0]
        f = lambda y, x: (y, 2 * c - x)
        kind = "vertical line x=%d" % c
    elif len(set(ys)) == 1:
        r = ys[0]
        f = lambda y, x: (2 * r - y, x)
        kind = "horizontal line y=%d" % r
    elif len(set(ys - xs)) == 1:
        k = int((ys - xs)[0])
        f = lambda y, x: (x + k, y - k)
        kind = "diagonal y-x=%d" % k
    else:
        s = int((ys + xs)[0])
        f = lambda y, x: (s - x, s - y)
        kind = "anti-diagonal y+x=%d" % s
    counts = {}
    for v in np.unique(g):
        v = int(v)
        if v in (bg, 1):
            continue
        counts[v] = int((g == v).sum())
    if not counts:
        emit(out, "No objects to mirror.")
        return out
    col = min(counts, key=lambda v: counts[v])
    for o in objects(g, bg=bg):
        if o["colour"] != col:
            continue
        for (y, x) in o["cells"]:
            ny, nx = f(y, x)
            if 0 <= ny < H and 0 <= nx < W and out[ny, nx] == bg:
                out[ny, nx] = col
        emit(out, "Mirrored a colour-%d object (rarest colour) across the %s." % (col, kind))
    emit(out, "All colour-%d objects mirrored; final grid." % col)
    return out
